class MyArrayList {
    int[] arr = {10, 20, 30};
    int size = 3;
    private int pos = 0;

    public boolean hasNext() { return pos < size; }
    public int next() { return arr[pos++]; }
}

public class Main {
    public static void main(String[] args) {
        MyArrayList l = new MyArrayList();
        while (l.hasNext()) {
            int a = l.next();
            while (l.hasNext()) {
                int b = l.next();
                System.out.println(a + " " + b);
            }
        }
    }
}

